// B12 PayFast Subscribe — Build the payload + the string to hash.
// Hashing happens in the next node (Crypto) so we don't need require('crypto').
//
// LIVE credentials are read from Railway env vars — set these BEFORE flipping to 'live':
//   PAYFAST_MERCHANT_ID
//   PAYFAST_MERCHANT_KEY
//   PAYFAST_PASSPHRASE
// (PayFast must also have verified the merchant account before live mode works.)

// ============ MODE — flip to 'live' when ready to take real money ============
const MODE = 'live'; // 'sandbox' (test, no real money) or 'live' (real charges)
// =============================================================================

// Sandbox uses PayFast's public test credentials (anyone can use these — safe to commit).
const MERCHANT_ID  = MODE === 'live' ? ($env['PAYFAST_MERCHANT_ID']  || '') : '10000100';
const MERCHANT_KEY = MODE === 'live' ? ($env['PAYFAST_MERCHANT_KEY'] || '') : '46f0cd694581a';
const PASSPHRASE   = MODE === 'live' ? ($env['PAYFAST_PASSPHRASE']   || '') : 'jt7NOE43FZPn';

const PAYFAST_URL = MODE === 'live'
  ? 'https://www.payfast.co.za/eng/process'
  : 'https://sandbox.payfast.co.za/eng/process';

const RETURN_URL = 'https://jarvis-nexus-lead-jkon.vercel.app/thank-you';
const CANCEL_URL = 'https://jarvis-nexus-lead-jkon.vercel.app/#pricing';
const NOTIFY_URL = 'https://n8n-production-71d9.up.railway.app/webhook/payfast-itn';

// Tier config — initial = setup fee + first month (charged today),
// recurring = monthly amount charged 30 days later, then monthly forever.
const TIERS = {
  starter: {
    name: 'Starter',
    amount: 4490.00,
    recurring: 1990.00,
    itemName: 'NSM · Starter Plan',
    itemDescription: 'Setup fee (R2,500) + first month (R1,990). Then R1,990/month auto-billed. Cancel anytime.'
  },
  operator: {
    name: 'Operator',
    amount: 8490.00,
    recurring: 3990.00,
    itemName: 'NSM · Operator Plan',
    itemDescription: 'Setup fee (R4,500) + first month (R3,990). Then R3,990/month auto-billed. 30-day guarantee.'
  },
  command: {
    name: 'Command',
    amount: 18490.00,
    recurring: 9990.00,
    itemName: 'NSM · Command Plan',
    itemDescription: 'Setup fee (R8,500) + first month (R9,990). Then R9,990/month auto-billed. White-glove support.'
  }
};

const tierKey = ($('Edit Fields — Tier').item.json['tier'] || 'starter').toLowerCase();
const tier = TIERS[tierKey] || TIERS.starter;
const paymentId = 'JN-' + Date.now() + '-' + Math.floor(Math.random() * 10000);

// Build payload in PayFast's documented field order (order matters for signature)
const data = {
  merchant_id: MERCHANT_ID,
  merchant_key: MERCHANT_KEY,
  return_url: RETURN_URL,
  cancel_url: CANCEL_URL,
  notify_url: NOTIFY_URL,
  m_payment_id: paymentId,
  amount: tier.amount.toFixed(2),
  item_name: tier.itemName,
  item_description: tier.itemDescription,
  custom_str1: tierKey,
  subscription_type: '1',
  recurring_amount: tier.recurring.toFixed(2),
  frequency: '3',  // 3 = Monthly
  cycles: '0'      // 0 = indefinite
};

// PayFast URL encoding: must match PHP urlencode() exactly.
// JS encodeURIComponent leaves !'()*~ unencoded; PHP urlencode does encode them.
// Spaces become '+' (PHP style), not '%20' (JS style).
function pfEncode(value) {
  return encodeURIComponent(String(value).trim())
    .replace(/%20/g, '+')
    .replace(/!/g, '%21')
    .replace(/'/g, '%27')
    .replace(/\(/g, '%28')
    .replace(/\)/g, '%29')
    .replace(/\*/g, '%2A')
    .replace(/~/g, '%7E');
}

const orderedKeys = Object.keys(data).filter(k => data[k] !== '' && data[k] != null);
const queryString = orderedKeys.map(k => k + '=' + pfEncode(data[k])).join('&');
const stringToHash = PASSPHRASE
  ? queryString + '&passphrase=' + pfEncode(PASSPHRASE)
  : queryString;

return [{
  json: {
    stringToHash: stringToHash,
    data: data,
    paymentId: paymentId,
    tierName: tier.name,
    payfastUrl: PAYFAST_URL,
    mode: MODE
  }
}];

// B12 — Build the auto-submitting HTML form using payload + signature

const input = $input.item.json;
const data = input['data'];
const signature = input['signature'];
const paymentId = input['paymentId'];
const tierName = input['tierName'];
const payfastUrl = input['payfastUrl'];

// Append the signature to the form fields
data.signature = signature;

function esc(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const inputs = Object.keys(data)
  .map(k => '  <input type="hidden" name="' + k + '" value="' + esc(data[k]) + '">')
  .join('\n');

const html = '<!DOCTYPE html>\n'
  + '<html lang="en"><head><meta charset="UTF-8">'
  + '<title>Redirecting to PayFast...</title>'
  + '<style>'
  + 'body{font-family:-apple-system,Arial,sans-serif;background:#08080c;color:#f5f5fa;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;padding:20px;}'
  + '.card{text-align:center;padding:40px;max-width:480px;}'
  + '.spinner{display:inline-block;width:36px;height:36px;border:3px solid rgba(99,102,241,0.2);border-top-color:#818cf8;border-radius:50%;animation:spin 800ms linear infinite;margin-bottom:24px;}'
  + '@keyframes spin{to{transform:rotate(360deg);}}'
  + '.label{font-family:monospace;font-size:11px;letter-spacing:0.18em;color:#818cf8;text-transform:uppercase;margin-bottom:10px;font-weight:600;}'
  + '.text{font-size:20px;font-weight:600;margin-bottom:8px;letter-spacing:-0.01em;}'
  + '.sub{font-size:13.5px;color:#a8a8c2;line-height:1.55;margin-bottom:24px;}'
  + '.ref{font-family:monospace;font-size:11px;color:#6b6b85;letter-spacing:0.06em;padding-top:20px;border-top:1px solid rgba(255,255,255,0.06);}'
  + '</style></head><body>'
  + '<div class="card"><div class="spinner"></div>'
  + '<div class="label">// NSM &middot; ' + tierName.toUpperCase() + '</div>'
  + '<div class="text">Securing your checkout...</div>'
  + '<div class="sub">Redirecting you to PayFast to complete payment.</div>'
  + '<div class="ref">REF &middot; ' + paymentId + '</div></div>'
  + '<form id="pf" action="' + payfastUrl + '" method="POST">\n' + inputs + '\n</form>'
  + '<script>setTimeout(function(){document.getElementById("pf").submit();}, 700);</script>'
  + '</body></html>';

return [{ json: { html: html, paymentId: paymentId, tier: tierName } }];
